--   DELETE FROM favourites WHERE sku IN (SKUS);
--   DELETE FROM stock_alerts WHERE sku IN (SKUS);
--   DELETE FROM stock_moves WHERE sku IN (SKUS);
--   DELETE FROM products WHERE sku IN (SKUS);
